#include <cstdio>
#include <algorithm>
using namespace std;

int main() {
    int N;
    scanf("%d", &N);
    int InArray[2 * N]; // using static array for performance
    long long sum = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &InArray[i]);
        sum += InArray[i]; // accumulate sum during input
        InArray[i + N] = InArray[i]; // circular behavior
    }

    long long MaxMin = 0;
    long long average = (sum + 2) / 3;

    for (int a1 = 0; a1 < N; a1++) {
        long long a1_sum = 0;
        for (int a2 = a1 + 1; a2 < (a1 + N); a2++) {
            a1_sum += InArray[a2 - 1];
            if (a1_sum < average) continue;

            long long average2 = (sum - a1_sum + 1) / 2;
            long long a2_sum = 0;
            for (int a3 = a2 + 1; a3 < (a1 + N); a3++) {
                a2_sum += InArray[a3 - 1];
                if (a2_sum < average2) continue;

                MaxMin = max(MaxMin, sum - a1_sum - a2_sum);
                break; // early break
            }
            break; // early break
        }
    }

    printf("%lld\n", MaxMin);
    return 0;
}

